INSERT INTO interview_stories (slug, title, company, situation, task, action, result, metrics, tags, sort_order) VALUES ('anomaly', 'Real-Time Anomaly Detection Dashboard', 'Safebooks AI', 'At Safebooks AI, our financial governance platform had to surface anomalies across 1M+ daily transactions, but the dashboard froze whenever clients loaded dense datasets.', 'I owned the rendering layer and needed to display 50,000+ live data points without dropping frames or blocking the UI.', 'I engineered a virtualized rendering pipeline with a canvas-based fallback for ultra-dense views, moved data preprocessing into web workers, and used requestAnimationFrame to batch 60fps updates.', 'We hit sub-200ms paint times with zero frame drops, and it became the feature 9 enterprise clients used daily.', NULL, ARRAY['performance', 'data viz', 'hardest technical problem', 'proud of']::text[], 0) ON CONFLICT (slug) DO NOTHING;
INSERT INTO interview_stories (slug, title, company, situation, task, action, result, metrics, tags, sort_order) VALUES ('perf', 'Enterprise Performance Optimization', 'Safebooks AI', 'The Safebooks app had degraded to a Lighthouse score of 62 — LCP 4.2s, INP 450ms — and enterprise users were complaining about sluggishness.', 'I was asked to lead a performance overhaul without a feature freeze.', 'I profiled with webpack-bundle-analyzer, introduced route-level code-splitting, replaced heavy deps (Moment→date-fns, lazy-loaded Chart.js), added Next.js image optimization and critical-CSS inlining.', 'Lighthouse went 62→95+, LCP 4.2s→1.5s, INP 450ms→100ms, and initial bundle shrank 50%.', NULL, ARRAY['performance', 'initiative', 'measurable impact']::text[], 1) ON CONFLICT (slug) DO NOTHING;
INSERT INTO interview_stories (slug, title, company, situation, task, action, result, metrics, tags, sort_order) VALUES ('types', 'Type-Safe Data Pipeline (TypeScript Generics)', 'Safebooks AI', 'Financial data flowed through many transformations and a single shape mismatch could corrupt a client''s reconciliation.', 'I needed to make the data layer provably safe end-to-end.', 'I built advanced generics for the data models, discriminated unions for state, and added Zod schemas to validate at every API boundary, then enforced strict TS config in CI.', 'Runtime errors dropped ~95%, we reached 85% coverage, and the team saved roughly 15 QA hours per sprint.', NULL, ARRAY['code quality', 'type safety', 'reducing bugs']::text[], 2) ON CONFLICT (slug) DO NOTHING;
INSERT INTO interview_stories (slug, title, company, situation, task, action, result, metrics, tags, sort_order) VALUES ('library', 'White-Label Component Library', 'Emerline', 'Five product teams at Emerline were each rebuilding the same UI, causing inconsistency and slow delivery.', 'I wanted a shared, themeable component library — but I had no authority to mandate adoption.', 'I built 60+ accessible components with token-based theming, the compound-component pattern with CVA, and Storybook + Chromatic for visual regression. I drove adoption through influence: a proof-of-concept, a data-backed presentation, and pairing sessions.', 'All 5 teams adopted it and UI development time dropped 30%.', NULL, ARRAY['design systems', 'leadership', 'influence without authority', 'cross-team', 'conflict']::text[], 3) ON CONFLICT (slug) DO NOTHING;
INSERT INTO interview_stories (slug, title, company, situation, task, action, result, metrics, tags, sort_order) VALUES ('migration', 'jQuery → React Migration', 'Inango Systems', 'Inango''s ISP monitoring tool was a 45,000-line jQuery app — 8.2s load, 2.3 bugs/week — that the business couldn''t afford to take offline.', 'I had to modernize it to React with zero downtime.', 'I applied the Strangler Fig pattern, built a StateBridge so jQuery and React could share state, scoped CSS to avoid conflicts, and migrated the highest-bug components first.', 'Load time dropped to 2.1s (−74%), bundle 1.2MB→340KB, bugs fell 83%, with zero downtime across the 8-month migration.', NULL, ARRAY['legacy modernization', 'migration', 'pragmatism', 'ambiguity', 'biggest challenge']::text[], 4) ON CONFLICT (slug) DO NOTHING;
INSERT INTO interview_stories (slug, title, company, situation, task, action, result, metrics, tags, sort_order) VALUES ('mentor', 'Mentorship & Technical Leadership', 'Emerline', 'Our team was growing with several junior developers but had no structured way to level them up.', 'As senior, I took ownership of growing the team''s capability.', 'I mentored 6 developers with pair programming where the junior drove, gave constructive code reviews, ran 12+ workshops on TS patterns and React performance, and started lunch-and-learns.', 'Two mentees were promoted to mid-level within a year and the knowledge-sharing culture stuck.', NULL, ARRAY['leadership', 'mentoring', 'teamwork', 'helping others']::text[], 5) ON CONFLICT (slug) DO NOTHING;
INSERT INTO interview_stories (slug, title, company, situation, task, action, result, metrics, tags, sort_order) VALUES ('pushback', 'Pushing Back on Requirements', 'Safebooks AI', 'A PM wanted all 15+ integrations loaded on the dashboard''s initial view.', 'I believed it would wreck the LCP we''d worked hard to protect.', 'Instead of just saying no, I built a quick prototype showing the performance hit, then proposed lazy-loading with usage data showing users touched only a few integrations at first.', 'The PM agreed; LCP stayed under 1.5s and we shipped a cleaner default experience.', NULL, ARRAY['disagreement', 'stakeholder', 'conflict', 'product collaboration', 'data-driven']::text[], 6) ON CONFLICT (slug) DO NOTHING;
