INSERT INTO interview_questions (category_id, story_id, question, model_answer, tips, difficulty, tags, is_custom, source) VALUES ((SELECT id FROM interview_categories WHERE slug = 'behavioral'), NULL, 'Why are you looking to leave / what are you looking for next?', NULL, '[{"point":"Stay positive — never trash a past employer.","detail":null},{"point":"Frame as ''looking for'' not ''running from'': architectural ownership, product impact, strong eng culture.","detail":null},{"point":"Tie to what this specific company offers.","detail":null}]'::jsonb, 'easy'::interview_difficulty, '{}', false, NULL);
INSERT INTO interview_questions (category_id, story_id, question, model_answer, tips, difficulty, tags, is_custom, source) VALUES ((SELECT id FROM interview_categories WHERE slug = 'behavioral'), NULL, 'What are your strengths?', NULL, '[{"point":"Pick 2-3 with evidence: performance engineering (Lighthouse 62→95), type-safe architecture, lifting teams via design systems.","detail":null},{"point":"One sentence of proof per strength, not a list of adjectives.","detail":null}]'::jsonb, 'easy'::interview_difficulty, '{}', false, NULL);
INSERT INTO interview_questions (category_id, story_id, question, model_answer, tips, difficulty, tags, is_custom, source) VALUES ((SELECT id FROM interview_categories WHERE slug = 'behavioral'), NULL, 'What''s a weakness you''re working on?', NULL, '[{"point":"Real but non-fatal + the system you''ve built around it.","detail":null},{"point":"E.g. early-career over-engineering → now I prototype the simplest version first and let data justify complexity (the lazy-load story).","detail":null},{"point":"Show growth, not confession.","detail":null}]'::jsonb, 'medium'::interview_difficulty, '{}', false, NULL);
INSERT INTO interview_questions (category_id, story_id, question, model_answer, tips, difficulty, tags, is_custom, source) VALUES ((SELECT id FROM interview_categories WHERE slug = 'behavioral'), NULL, 'Tell me about a time you failed or shipped a bug to production.', NULL, '[{"point":"Own it plainly, no blame.","detail":null},{"point":"Focus on the response: how you detected, contained, and the process change that prevented recurrence.","detail":null},{"point":"If needed: a regression caught late → added Chromatic visual tests + stricter CI gates.","detail":null}]'::jsonb, 'hard'::interview_difficulty, '{}', false, NULL);
INSERT INTO interview_questions (category_id, story_id, question, model_answer, tips, difficulty, tags, is_custom, source) VALUES ((SELECT id FROM interview_categories WHERE slug = 'behavioral'), NULL, 'How do you handle competing priorities or tight deadlines?', NULL, '[{"point":"Clarify the actual business goal, surface trade-offs early, negotiate scope not quality.","detail":null},{"point":"Reference delivering 3 client apps under budget at Emerline.","detail":null}]'::jsonb, 'medium'::interview_difficulty, '{}', false, NULL);
INSERT INTO interview_questions (category_id, story_id, question, model_answer, tips, difficulty, tags, is_custom, source) VALUES ((SELECT id FROM interview_categories WHERE slug = 'behavioral'), NULL, 'Describe giving difficult feedback to a peer.', NULL, '[{"point":"Private, specific, behavior-not-person, paired with a path forward.","detail":null},{"point":"Lean on your code-review and mentoring experience.","detail":null}]'::jsonb, 'medium'::interview_difficulty, '{}', false, NULL);
INSERT INTO interview_questions (category_id, story_id, question, model_answer, tips, difficulty, tags, is_custom, source) VALUES ((SELECT id FROM interview_categories WHERE slug = 'frontend'), NULL, 'How do you approach optimizing Core Web Vitals (LCP, INP, CLS)?', NULL, '[{"point":"LCP: prioritize/preload hero asset, server-render, optimize images, reduce render-blocking.","detail":null},{"point":"INP: break up long tasks, debounce, move work to web workers, useTransition.","detail":null},{"point":"CLS: reserve space (width/height, aspect-ratio), avoid late-injected content.","detail":null},{"point":"Cite Safebooks: 62→95, LCP 4.2→1.5s.","detail":null}]'::jsonb, 'medium'::interview_difficulty, '{}', false, NULL);
INSERT INTO interview_questions (category_id, story_id, question, model_answer, tips, difficulty, tags, is_custom, source) VALUES ((SELECT id FROM interview_categories WHERE slug = 'frontend'), NULL, 'Explain the React rendering lifecycle and when components re-render.', NULL, '[{"point":"Re-render triggers: state change, parent re-render, context change.","detail":null},{"point":"Reconciliation diffs the virtual DOM; keys matter for lists.","detail":null},{"point":"Optimize with memo/useMemo/useCallback — but only after measuring.","detail":null}]'::jsonb, 'medium'::interview_difficulty, '{}', false, NULL);
INSERT INTO interview_questions (category_id, story_id, question, model_answer, tips, difficulty, tags, is_custom, source) VALUES ((SELECT id FROM interview_categories WHERE slug = 'frontend'), (SELECT id FROM interview_stories WHERE slug = 'anomaly'), 'How would you render 50,000 rows/points without freezing the UI?', NULL, '[{"point":"Virtualization (react-window/virtual), canvas for ultra-dense, web workers for prep, rAF batching.","detail":null},{"point":"This is literally your Safebooks dashboard story.","detail":null}]'::jsonb, 'hard'::interview_difficulty, '{}', false, NULL);
INSERT INTO interview_questions (category_id, story_id, question, model_answer, tips, difficulty, tags, is_custom, source) VALUES ((SELECT id FROM interview_categories WHERE slug = 'frontend'), NULL, 'When do you reach for useMemo / useCallback, and when is it premature?', NULL, '[{"point":"Default: don''t. Add when profiling shows a real cost or to stabilize deps passed to memoized children.","detail":null},{"point":"Over-memoization adds complexity and its own cost.","detail":null},{"point":"Measure first (React Profiler).","detail":null}]'::jsonb, 'medium'::interview_difficulty, '{}', false, NULL);
INSERT INTO interview_questions (category_id, story_id, question, model_answer, tips, difficulty, tags, is_custom, source) VALUES ((SELECT id FROM interview_categories WHERE slug = 'frontend'), NULL, 'Compare client-side, server-side, and static rendering in Next.js.', NULL, '[{"point":"CSR: interactive, slow first paint, bad SEO.","detail":null},{"point":"SSR: fresh per request, good SEO, server cost.","detail":null},{"point":"SSG/ISR: fastest, cacheable, best for mostly-static content.","detail":null},{"point":"RSC: server components reduce client JS — discuss the App Router split.","detail":null}]'::jsonb, 'medium'::interview_difficulty, '{}', false, NULL);
INSERT INTO interview_questions (category_id, story_id, question, model_answer, tips, difficulty, tags, is_custom, source) VALUES ((SELECT id FROM interview_categories WHERE slug = 'frontend'), NULL, 'How do you architect state in a large React app?', NULL, '[{"point":"Layer it: local state → URL state → server cache (TanStack Query) → global client state (Zustand/Redux only for truly shared UI state).","detail":null},{"point":"Avoid putting server data in Redux — it goes stale.","detail":null},{"point":"Co-locate state as close to use as possible.","detail":null}]'::jsonb, 'hard'::interview_difficulty, '{}', false, NULL);
INSERT INTO interview_questions (category_id, story_id, question, model_answer, tips, difficulty, tags, is_custom, source) VALUES ((SELECT id FROM interview_categories WHERE slug = 'frontend'), NULL, 'How do you ensure accessibility (a11y) in your components?', NULL, '[{"point":"Semantic HTML first, ARIA only to fill gaps.","detail":null},{"point":"Keyboard nav + focus management, color contrast, screen-reader testing.","detail":null},{"point":"Reference: 60+ accessible components in the Emerline library.","detail":null}]'::jsonb, 'medium'::interview_difficulty, '{}', false, NULL);
INSERT INTO interview_questions (category_id, story_id, question, model_answer, tips, difficulty, tags, is_custom, source) VALUES ((SELECT id FROM interview_categories WHERE slug = 'frontend'), (SELECT id FROM interview_stories WHERE slug = 'types'), 'How do you use TypeScript to prevent runtime errors at scale?', NULL, '[{"point":"Generics for models, discriminated unions for state, Zod at API boundaries, strict config in CI.","detail":null},{"point":"Safebooks: ~95% fewer runtime errors.","detail":null}]'::jsonb, 'medium'::interview_difficulty, '{}', false, NULL);
INSERT INTO interview_questions (category_id, story_id, question, model_answer, tips, difficulty, tags, is_custom, source) VALUES ((SELECT id FROM interview_categories WHERE slug = 'frontend'), NULL, 'What''s your testing strategy for a frontend app?', NULL, '[{"point":"Trophy not pyramid: lots of integration (RTL), some unit, few E2E (Playwright/Cypress), visual regression (Chromatic).","detail":null},{"point":"Test behavior users care about, not implementation details.","detail":null},{"point":"85% coverage at Safebooks was a byproduct, not the goal.","detail":null}]'::jsonb, 'medium'::interview_difficulty, '{}', false, NULL);
INSERT INTO interview_questions (category_id, story_id, question, model_answer, tips, difficulty, tags, is_custom, source) VALUES ((SELECT id FROM interview_categories WHERE slug = 'frontend'), (SELECT id FROM interview_stories WHERE slug = 'migration'), 'How would you migrate a large legacy app to React with zero downtime?', NULL, '[]'::jsonb, 'hard'::interview_difficulty, '{}', false, NULL);
INSERT INTO interview_questions (category_id, story_id, question, model_answer, tips, difficulty, tags, is_custom, source) VALUES ((SELECT id FROM interview_categories WHERE slug = 'frontend'), NULL, 'How do you keep bundle size down?', NULL, '[{"point":"Code-split by route + heavy component, tree-shakeable deps, analyze with webpack-bundle-analyzer, replace heavy libs (Moment→date-fns).","detail":null},{"point":"Safebooks: cut initial bundle 50%.","detail":null}]'::jsonb, 'medium'::interview_difficulty, '{}', false, NULL);
INSERT INTO interview_questions (category_id, story_id, question, model_answer, tips, difficulty, tags, is_custom, source) VALUES ((SELECT id FROM interview_categories WHERE slug = 'frontend'), NULL, 'What''s the difference between controlled and uncontrolled components?', NULL, '[{"point":"Controlled: value driven by React state, single source of truth.","detail":null},{"point":"Uncontrolled: DOM holds the value, read via ref.","detail":null},{"point":"Controlled for validation/dynamic UI; uncontrolled for simple/perf-sensitive forms.","detail":null}]'::jsonb, 'easy'::interview_difficulty, '{}', false, NULL);
INSERT INTO interview_questions (category_id, story_id, question, model_answer, tips, difficulty, tags, is_custom, source) VALUES ((SELECT id FROM interview_categories WHERE slug = 'frontend'), NULL, 'Walk me through debugging a memory leak / performance regression in production.', NULL, '[{"point":"Reproduce + measure (Performance panel, heap snapshots, React Profiler).","detail":null},{"point":"Common causes: uncleaned listeners/intervals, growing closures, retained DOM, unbounded caches.","detail":null},{"point":"Bisect with git, add a regression test, monitor (RUM).","detail":null}]'::jsonb, 'hard'::interview_difficulty, '{}', false, NULL);
INSERT INTO interview_questions (category_id, story_id, question, model_answer, tips, difficulty, tags, is_custom, source) VALUES ((SELECT id FROM interview_categories WHERE slug = 'system-design'), NULL, 'Design a real-time analytics dashboard front-end.', NULL, '[{"point":"Clarify scale (points, update freq), then: data layer (WebSocket/SSE + query cache), rendering (virtualize/canvas), state (normalized store).","detail":null},{"point":"Discuss backpressure, throttling updates, offline/reconnect.","detail":null},{"point":"Anchor to your Safebooks dashboard.","detail":null}]'::jsonb, 'hard'::interview_difficulty, '{}', false, NULL);
INSERT INTO interview_questions (category_id, story_id, question, model_answer, tips, difficulty, tags, is_custom, source) VALUES ((SELECT id FROM interview_categories WHERE slug = 'system-design'), (SELECT id FROM interview_stories WHERE slug = 'library'), 'Design a reusable, themeable design system for multiple product teams.', NULL, '[{"point":"Tokens → primitives → composites; theming via CSS custom props; versioning + changelog; Storybook docs; visual regression in CI.","detail":null},{"point":"Adoption is a people problem — POC, data, pairing.","detail":null}]'::jsonb, 'hard'::interview_difficulty, '{}', false, NULL);
INSERT INTO interview_questions (category_id, story_id, question, model_answer, tips, difficulty, tags, is_custom, source) VALUES ((SELECT id FROM interview_categories WHERE slug = 'system-design'), NULL, 'How would you structure a Next.js app for a team of 10+ engineers?', NULL, '[{"point":"Feature-based modules, clear boundaries, shared UI lib, typed API layer, conventions enforced by ESLint/Prettier/Husky.","detail":null},{"point":"Document architecture decisions (ADRs); strict CI gates.","detail":null}]'::jsonb, 'medium'::interview_difficulty, '{}', false, NULL);
INSERT INTO interview_questions (category_id, story_id, question, model_answer, tips, difficulty, tags, is_custom, source) VALUES ((SELECT id FROM interview_categories WHERE slug = 'system-design'), NULL, 'How do you handle data fetching, caching, and loading states cleanly?', NULL, '[{"point":"TanStack Query for server cache: stale-while-revalidate, retries, dedup.","detail":null},{"point":"Skeletons over spinners, optimistic updates where safe, error boundaries.","detail":null},{"point":"Suspense/RSC for streaming where it fits.","detail":null}]'::jsonb, 'medium'::interview_difficulty, '{}', false, NULL);
