INSERT INTO interview_questions (category_id, story_id, question, model_answer, tips, difficulty, tags, is_custom, source) VALUES ((SELECT id FROM interview_categories WHERE slug = 'leadership'), NULL, 'How do you give and receive code review feedback?', NULL, '[{"point":"Give: specific, kind, explain the why, distinguish blocking vs nit.","detail":null},{"point":"Receive: assume good intent, ask questions, don''t defend reflexively.","detail":null},{"point":"Reviews are teaching moments, not gates.","detail":null}]'::jsonb, 'medium'::interview_difficulty, '{}', false, NULL);
INSERT INTO interview_questions (category_id, story_id, question, model_answer, tips, difficulty, tags, is_custom, source) VALUES ((SELECT id FROM interview_categories WHERE slug = 'leadership'), (SELECT id FROM interview_stories WHERE slug = 'pushback'), 'How do you handle disagreement with a product decision?', NULL, '[]'::jsonb, 'hard'::interview_difficulty, '{}', false, NULL);
INSERT INTO interview_questions (category_id, story_id, question, model_answer, tips, difficulty, tags, is_custom, source) VALUES ((SELECT id FROM interview_categories WHERE slug = 'leadership'), NULL, 'How do you collaborate across time zones?', NULL, '[{"point":"Async-first: written context, clear PRs, recorded decisions.","detail":null},{"point":"Protect overlap hours for sync work.","detail":null},{"point":"4+ years across US/EU/UK; EET overlaps both.","detail":null}]'::jsonb, 'medium'::interview_difficulty, '{}', false, NULL);
INSERT INTO interview_questions (category_id, story_id, question, model_answer, tips, difficulty, tags, is_custom, source) VALUES ((SELECT id FROM interview_categories WHERE slug = 'product'), NULL, 'How do you balance speed of delivery with code quality?', NULL, '[{"point":"Quality that protects velocity (types, tests, CI) is non-negotiable; gold-plating is.","detail":null},{"point":"Negotiate scope, not standards. Ship the simplest correct version, iterate.","detail":null}]'::jsonb, 'medium'::interview_difficulty, '{}', false, NULL);
INSERT INTO interview_questions (category_id, story_id, question, model_answer, tips, difficulty, tags, is_custom, source) VALUES ((SELECT id FROM interview_categories WHERE slug = 'product'), NULL, 'How do you decide what to build when requirements are vague?', NULL, '[{"point":"Clarify the user problem and success metric first, then smallest slice that tests the hypothesis.","detail":null},{"point":"Prototype to surface unknowns (your lazy-load prototype example).","detail":null}]'::jsonb, 'medium'::interview_difficulty, '{}', false, NULL);
INSERT INTO interview_questions (category_id, story_id, question, model_answer, tips, difficulty, tags, is_custom, source) VALUES ((SELECT id FROM interview_categories WHERE slug = 'product'), NULL, 'How do you keep up with the fast-moving frontend ecosystem?', NULL, '[{"point":"Curated sources, build small experiments, evaluate by problem-fit not hype.","detail":null},{"point":"Adopt deliberately — bring data before pushing a new tool (CVA, RSC).","detail":null}]'::jsonb, 'easy'::interview_difficulty, '{}', false, NULL);
INSERT INTO interview_questions (category_id, story_id, question, model_answer, tips, difficulty, tags, is_custom, source) VALUES ((SELECT id FROM interview_categories WHERE slug = 'logistics'), NULL, 'You''re based in Ukraine and remote — how does that work for us?', NULL, '[{"point":"4+ years remote with international teams; EET overlaps EU fully and US East Coast mornings.","detail":null},{"point":"FOP contractor model (~5% tax), no visa/sponsorship needed.","detail":null},{"point":"Ukraine IT exported $6.66B in 2025; 96% wartime contract retention — stable and proven.","detail":null}]'::jsonb, 'easy'::interview_difficulty, '{}', false, NULL);
INSERT INTO interview_questions (category_id, story_id, question, model_answer, tips, difficulty, tags, is_custom, source) VALUES ((SELECT id FROM interview_categories WHERE slug = 'logistics'), NULL, 'What''s your availability and notice period?', NULL, '[{"point":"Available immediately.","detail":null},{"point":"Open to full-time or B2B/contract.","detail":null}]'::jsonb, 'easy'::interview_difficulty, '{}', false, NULL);
INSERT INTO interview_questions (category_id, story_id, question, model_answer, tips, difficulty, tags, is_custom, source) VALUES ((SELECT id FROM interview_categories WHERE slug = 'logistics'), NULL, 'What are your salary expectations?', NULL, '[{"point":"Foreign companies: $5,000–7,000/mo ($60–84K base), up to $130K+ for top-tier.","detail":null},{"point":"Ukrainian: €4,500–5,000/mo.","detail":null},{"point":"Give a range, anchor on value, ask about their band.","detail":null}]'::jsonb, 'medium'::interview_difficulty, '{}', false, NULL);
INSERT INTO interview_questions (category_id, story_id, question, model_answer, tips, difficulty, tags, is_custom, source) VALUES ((SELECT id FROM interview_categories WHERE slug = 'closing'), NULL, 'What questions should I ask the interviewer?', NULL, '[{"point":"What does the FE architecture look like today, and the biggest pain point?","detail":null},{"point":"How are technical decisions made — who owns them?","detail":null},{"point":"What does success look like in 6 months for this role?","detail":null},{"point":"How does the team balance shipping speed with quality?","detail":null},{"point":"What''s the on-call / incident culture for frontend?","detail":null}]'::jsonb, 'easy'::interview_difficulty, '{}', false, NULL);
INSERT INTO interview_questions (category_id, story_id, question, model_answer, tips, difficulty, tags, is_custom, source) VALUES ((SELECT id FROM interview_categories WHERE slug = 'closing'), NULL, 'Where do you see yourself in a few years?', NULL, '[{"point":"Growing into staff/lead-level technical ownership and mentoring.","detail":null},{"point":"Stay grounded in continuing to build product impact, not just titles.","detail":null},{"point":"Tie to growth paths at this company.","detail":null}]'::jsonb, 'easy'::interview_difficulty, '{}', false, NULL);
INSERT INTO interview_questions (category_id, story_id, question, model_answer, tips, difficulty, tags, is_custom, source) VALUES ((SELECT id FROM interview_categories WHERE slug = 'houston-technical'), NULL, 'Their app is a dense financial dashboard built on Chart.js + Recharts. How do you decide which library renders what — and when do you drop to raw canvas / D3?', NULL, '[{"point":"Recharts (SVG) for moderate, interactive charts.","detail":"Recharts renders every series as SVG DOM nodes, so React owns them directly — you get declarative composition, trivial hover/click handlers, and crisp vector output. The catch is that each point, line and label is a node, and the browser''s layout/paint cost balloons once you push past a few thousand. Reach for it when interactivity matters and the point count is modest: comparison bars, a few trend lines, annotated scatter."},{"point":"Chart.js (canvas) for dense series.","detail":"Chart.js paints to a single canvas, so 10k points cost one bitmap draw instead of 10k DOM nodes — far cheaper to render, pan and zoom. The trade-off is there are no elements to attach events to, so interactivity (tooltips, hover highlight, click-to-select) is something you compute against the data yourself. Use it when raw density beats rich per-element interaction."},{"point":"Drop to raw canvas / WebGL / D3 only when profiling proves it.","detail":"If even Chart.js can''t hold 60fps — tens of thousands of streaming points — you hand-roll canvas or go WebGL (regl, PixiJS), and use D3 for the maths (scales, axes, layouts) rather than its DOM rendering. It''s a last resort because you give up a lot of free behaviour. The senior signal is the sequencing: prove the ceiling with numbers before taking on that complexity."},{"point":"Anchor to Safebooks.","detail":"Make it concrete: at Safebooks I rendered 50k+ live points sub-200ms with a virtualized pipeline and a canvas fallback for the densest views, so I''ve made exactly this SVG-vs-canvas call in production. That turns an abstract answer into proof you''ve shipped it."}]'::jsonb, 'hard'::interview_difficulty, '{}', false, NULL);
INSERT INTO interview_questions (category_id, story_id, question, model_answer, tips, difficulty, tags, is_custom, source) VALUES ((SELECT id FROM interview_categories WHERE slug = 'houston-technical'), NULL, 'The stack is React Context, no Redux. How do you architect state with Context without causing re-render storms in a data-dense app?', NULL, '[{"point":"Know the failure mode: Context re-renders every consumer.","detail":"When a provider''s value changes, React re-renders every component that reads that context — there''s no partial subscription. In a dense dashboard, one filter change can redraw every chart on the same context, which is the classic ''why is the whole screen re-rendering'' bug. Naming this up front shows you understand Context''s mechanics, not just its API."},{"point":"Split contexts by concern AND change-frequency.","detail":"Put slow, broadly-needed data (auth/session, theme) in one provider and volatile data (live values, filters, hover) in separate providers scoped near where they''re used. A high-frequency update then only re-renders the small subtree that cares, not the whole app. It''s the highest-leverage fix and costs nothing architecturally."},{"point":"Stabilize the value; split state from dispatch.","detail":"Always wrap a provider''s value in useMemo so consumers aren''t handed a fresh object every render. Then expose state and the updater through two separate contexts — components that only fire actions (a button) subscribe to dispatch and never re-render when state changes. These two habits kill most accidental re-renders."},{"point":"For truly high-frequency data, use a selector store.","detail":"Context is all-or-nothing — it can''t do ''only re-render if this one field changed.'' When data updates many times a second, a selector-based store (useSyncExternalStore, or a tiny lib like Zustand/Jotai) lets each component subscribe to just its slice. I''d raise this as complementary if density grows, never as ''rip out your architecture'' — they deliberately avoid Redux, so respect that."},{"point":"Layer the whole state story.","detail":"Show the model: local component state → URL/query-string state for a shareable view → server cache (they call FastAPI via Axios; I''d add TanStack-Query-style caching with stale-while-revalidate) → Context only for genuinely shared client UI state. Most ''global state'' problems vanish once server data lives in a query cache instead of a global store."}]'::jsonb, 'hard'::interview_difficulty, '{}', false, NULL);
INSERT INTO interview_questions (category_id, story_id, question, model_answer, tips, difficulty, tags, is_custom, source) VALUES ((SELECT id FROM interview_categories WHERE slug = 'houston-technical'), NULL, 'They want someone who ''profiles before optimising''. Walk through how you''d profile this dashboard.', NULL, '[{"point":"Measure first — the right tool per problem.","detail":"Name the toolbox and what each catches: React DevTools Profiler for which components re-render and how often; the Performance panel for long tasks and jank; heap snapshots and the allocation timeline for leaks; the bundle analyzer for download weight. Optimising without these is guessing, and guesses usually add complexity for no measured win."},{"point":"Charts have their own profiling tells.","detail":"For a data-dense view I specifically check SVG/DOM node counts, the split of scripting vs paint vs recalc-style in a flame chart, and whether hovering a tooltip triggers a re-render cascade through the chart tree. Those three findings point straight at the fix — virtualize, move to canvas, or isolate the tooltip."},{"point":"Fix the root cause, not the symptom (their words).","detail":"If the profiler shows a tooltip re-rendering the whole chart, the symptom fix is sprinkling memo everywhere; the root fix is isolating the tooltip into its own subtree or pulling its state out of the shared provider. Framing it this way mirrors their JD value and shows judgement about which fix actually holds."},{"point":"Anchor to the Safebooks numbers.","detail":"Make it concrete: Lighthouse 62→95, LCP 4.2→1.5s, INP 450→100ms — every one of those came from a profiler trace, not a hunch. Numbers plus method is exactly the evidence-driven style Harry will respond to."}]'::jsonb, 'medium'::interview_difficulty, '{}', false, NULL);
INSERT INTO interview_questions (category_id, story_id, question, model_answer, tips, difficulty, tags, is_custom, source) VALUES ((SELECT id FROM interview_categories WHERE slug = 'houston-technical'), NULL, 'You''d ''own the frontend'' and inherit a clean codebase with set conventions. How do you ramp without rewriting everything?', NULL, '[{"point":"Respect the conventions before changing them.","detail":"Read the code, the README and recent PRs first, and assume the existing choices were made for reasons you can''t yet see. Senior engineers earn the right to change a codebase by first proving they understand it; juniors reach for a rewrite. This signals you won''t be a bull in their (deliberately tidy) china shop."},{"point":"Map the architecture, find the leverage points.","detail":"Spend the first days building a mental model — data flow, state boundaries, where complexity and bugs cluster — and write it down. That map tells you the few changes that buy the most, instead of scattering low-value edits. It also becomes documentation the small team probably lacks."},{"point":"Earn trust with small, high-signal wins first.","detail":"Land a contained but real win early — a measured perf fix, a flaky test killed, a confusing module clarified — before proposing anything structural. It proves competence and taste, so when you do argue for a bigger change they''re inclined to say yes. Trust is the currency that lets you actually own the frontend, not just on paper."},{"point":"Anchor: I improve big existing systems incrementally.","detail":"Point to Inango: the jQuery→React migration was the opposite of a rewrite — Strangler Fig, incremental, zero downtime on a 45k-line app. It proves you can make inherited code better without breaking what works."}]'::jsonb, 'medium'::interview_difficulty, '{}', false, NULL);
INSERT INTO interview_questions (category_id, story_id, question, model_answer, tips, difficulty, tags, is_custom, source) VALUES ((SELECT id FROM interview_categories WHERE slug = 'houston-technical'), NULL, 'The React app sits on a Python/FastAPI backend, called via Axios. How do you keep that API boundary safe and clean?', NULL, '[{"point":"Treat the boundary as untrusted; validate at the edge.","detail":"Even with a typed backend, the frontend should assume responses can drift or break — deploys, versions and nulls happen. Validating where data enters the app means a bad payload fails loudly at one known place instead of corrupting a chart three layers deep. For analysts making real decisions, that safety isn''t optional."},{"point":"Generate types from FastAPI''s OpenAPI schema.","detail":"FastAPI auto-publishes an OpenAPI spec, so I''d run openapi-typescript to generate TypeScript types straight from it. Now the frontend''s types track the backend automatically — when the API changes, the build breaks instead of production. It removes a whole class of hand-written, drift-prone interface code."},{"point":"Add runtime validation with Zod on responses.","detail":"Types vanish at runtime, so I parse responses through Zod schemas at the boundary — Pydantic validates server-side, this mirrors it client-side. You get a guaranteed shape plus one clean place to handle failure. It''s the same discipline that cut my Safebooks runtime errors ~95%."},{"point":"Centralize Axios and model every state.","detail":"One configured Axios instance with interceptors for auth tokens and error normalization, wrapped in thin typed functions, beats fetch calls scattered everywhere. And every request models loading, error and empty explicitly — an analyst should never see a blank pane and wonder if it''s broken or just empty."}]'::jsonb, 'medium'::interview_difficulty, '{}', false, NULL);
INSERT INTO interview_questions (category_id, story_id, question, model_answer, tips, difficulty, tags, is_custom, source) VALUES ((SELECT id FROM interview_categories WHERE slug = 'houston-technical'), NULL, 'They use Clerk for auth and deploy on Vercel — you haven''t shipped Clerk. How do you handle that honestly?', NULL, '[{"point":"Be straight about Clerk; show the transferable model.","detail":"Say plainly you haven''t shipped Clerk, then show you understand the shape: hosted auth means sessions, protected routes, token refresh and role-gating — all of which you''ve done with Firebase Auth. Clerk is a nicer wrapper around the same concepts. Demonstrating the mental model convinces more than claiming experience you don''t have."},{"point":"Vercel you can speak to firsthand.","detail":"You''ve deployed Next.js on Vercel — preview deploys per PR, environment management, edge/serverless functions — so talk about it concretely. It shows you understand their deploy story without overclaiming."},{"point":"Use their own framing: ''learn quickly''.","detail":"The JD literally says you don''t need to have used all of it, just learn fast. Give a real example of picking something up quickly — adopting CVA for the component library, or React Server Components — so ''fast learner'' is evidenced, not asserted."},{"point":"Never bluff depth — it reads as senior.","detail":"Founders probe edges; a confident ''I haven''t used that, here''s how I''d get productive'' lands better than a vague claim that collapses under one follow-up. Calibrated honesty is itself a seniority signal."}]'::jsonb, 'medium'::interview_difficulty, '{}', false, NULL);
INSERT INTO interview_questions (category_id, story_id, question, model_answer, tips, difficulty, tags, is_custom, source) VALUES ((SELECT id FROM interview_categories WHERE slug = 'houston-technical'), NULL, '''Cares whether a tooltip feels right.'' Make the case for craft on a dense financial chart.', NULL, '[{"point":"Tooltips on canvas are genuinely hard.","detail":"With SVG you attach a handler to each element; on a canvas there are no elements, so you find the nearest data point by hit-testing the cursor against the data (a spatial index or quadtree for big sets). Explaining this shows you know the gap between an easy SVG tooltip and the real work in a dense canvas chart."},{"point":"Position so it never covers the cursor or clips.","detail":"A tooltip that hides the very point you''re inspecting, or runs off the screen edge, is worse than none — so you flip it to the other side near edges and offset it from the cursor. Small details, but exactly the ''feel'' the JD obsesses over."},{"point":"Make it fast and honest.","detail":"Debounce or rAF the hover so it doesn''t re-layout on every mousemove — jank destroys the feel — and show numbers at the right precision, with units and aligned digits, never implying more precision than the data has. For financial analysts a misleading readout is a real problem, not a cosmetic one."},{"point":"Don''t forget accessibility.","detail":"Hover-only data excludes keyboard and screen-reader users, so the underlying values should be reachable another way. Raising a11y unprompted signals genuine craft maturity, which is precisely what they''re screening for."}]'::jsonb, 'medium'::interview_difficulty, '{}', false, NULL);
INSERT INTO interview_questions (category_id, story_id, question, model_answer, tips, difficulty, tags, is_custom, source) VALUES ((SELECT id FROM interview_categories WHERE slug = 'houston-technical'), NULL, 'The product does regression analysis & peer comparison. How would you present statistical output in a legible, trustworthy UI?', NULL, '[{"point":"Show uncertainty; don''t hide it.","detail":"A regression line without its confidence interval invites false confidence, so I''d surface error bands, make R² and residuals available on demand, and keep sample size visible — enough for an analyst to judge how much to trust it. With a mathematician founder, getting this right is table stakes."},{"point":"Frame peer comparison fairly.","detail":"Use percentile or rank framing against a clearly-stated baseline, and avoid the classic distortions — dual y-axes that imply correlation, truncated zero-baselines that exaggerate gaps. The UI should make the honest comparison the easy one to read."},{"point":"Progressive disclosure for two audiences.","detail":"Give a clean default tuned to the decision the analyst is making, with drill-down to the statistics underneath for when they want to interrogate it. That respects both the quick scan and the deep dive without cluttering either."},{"point":"Lead with your Physics edge.","detail":"Say it directly: a Master''s in Physics means you''re comfortable with regression and error analysis and won''t misrepresent it visually — and you can talk to Harry in his own language. It''s a genuine differentiator most frontend candidates simply won''t have."}]'::jsonb, 'hard'::interview_difficulty, '{}', false, NULL);
INSERT INTO interview_questions (category_id, story_id, question, model_answer, tips, difficulty, tags, is_custom, source) VALUES ((SELECT id FROM interview_categories WHERE slug = 'houston-technical'), NULL, 'How would you render 50,000+ data points without freezing the UI?', NULL, '[{"point":"Four levers: virtualize, canvas, workers, rAF.","detail":"Virtualize long lists/tables so you only mount what''s on screen (react-window); render dense series to canvas; do heavy data prep in a Web Worker so the main thread stays free for interaction; and batch updates with requestAnimationFrame to a steady 60fps instead of thrashing on every tick. Each targets a different bottleneck — DOM count, paint cost, blocking compute, update cadence."},{"point":"Downsample for overview, full-res on zoom.","detail":"Zoomed out, the screen has fewer pixels than data points, so plotting all of them is wasted work and visual noise — an algorithm like LTTB keeps the shape with a fraction of the points. When the user zooms in you load full resolution for just that window, and it feels instant and accurate."},{"point":"Anchor to Safebooks, hard.","detail":"This is your signature story: 50k+ points sub-200ms, zero dropped frames, used daily by 9 enterprise clients. It maps one-to-one onto their product, so make the parallel explicit rather than leaving them to infer it."},{"point":"Point them to the full STAR.","detail":"The complete Situation→Result version lives in your Story Bank as ''Real-Time Anomaly Detection Dashboard'' — have its spine memorised so you can tell it in 90 seconds if they ask you to go deep."}]'::jsonb, 'hard'::interview_difficulty, '{}', false, NULL);
INSERT INTO interview_questions (category_id, story_id, question, model_answer, tips, difficulty, tags, is_custom, source) VALUES ((SELECT id FROM interview_categories WHERE slug = 'houston-technical'), NULL, 'They prize ''fixing root causes, not symptoms.'' Give an example and your debugging method.', NULL, '[{"point":"Have a repeatable method.","detail":"State it as a pipeline: reproduce reliably → measure to localise → bisect (git, or by disabling suspects) → fix the cause → add a regression test → monitor in production. A named method reassures them you debug systematically rather than poking until it works."},{"point":"Give a concrete root-vs-symptom example.","detail":"Use the re-render storm: a ''slow dashboard'' that looked like it needed more memoization was actually one over-broad Context provider. Memo would have masked it; splitting the provider fixed it for good. The example proves you can tell a patch from a cure."},{"point":"Stop recurrence, don''t just close the ticket.","detail":"Pair the fix with the thing that prevents its return — a regression test, a CI gate, visual-regression coverage on charts. That''s the difference between firefighting and actually improving the codebase, which is what owning it means."}]'::jsonb, 'medium'::interview_difficulty, '{}', false, NULL);
INSERT INTO interview_questions (category_id, story_id, question, model_answer, tips, difficulty, tags, is_custom, source) VALUES ((SELECT id FROM interview_categories WHERE slug = 'houston-technical'), NULL, 'They list Next.js & React Router as nice-to-haves. Where do you stand?', NULL, '[{"point":"Next.js: advanced.","detail":"Be specific so it''s credible: App Router, React Server Components, the SSR/SSG/ISR rendering modes and when each fits, and built-in image optimization — Safebooks ran on Next.js. Specifics beat a flat ''I know Next.js.''"},{"point":"React Router: solid, and probably what they use.","detail":"Their stack (Vercel + Context + Axios, no mention of Next) suggests a Vite single-page app, where client-side routing via React Router matters — nested routes, loaders, route-level code-splitting. Showing you inferred their likely setup from the stack is itself a senior signal."},{"point":"Comfortable across both worlds.","detail":"Frame it as range: Next.js when SSR/SEO/streaming earns its keep, a plain React + Router SPA for an app-shell dashboard behind auth (which theirs likely is). You''re not dogmatic about one rendering model."}]'::jsonb, 'easy'::interview_difficulty, '{}', false, NULL);
INSERT INTO interview_questions (category_id, story_id, question, model_answer, tips, difficulty, tags, is_custom, source) VALUES ((SELECT id FROM interview_categories WHERE slug = 'houston-day-to-day'), NULL, 'What would your first 30 / 60 / 90 days look like owning this frontend?', NULL, '[{"point":"First 30 — learn deeply, ship small.","detail":"Get fluent in the code, the conventions, the product, and crucially the analysts who use it, while shipping small safe fixes to build flow and trust. The goal is an accurate mental model, not big moves. Resist the urge to prove yourself with a flashy change in week one."},{"point":"By 60 — one meaningful, measured improvement.","detail":"Land a single change with a number attached — a perf win, an a11y pass, a flaky area tamed — and write the architecture map the small team probably never had time for. Visible impact plus useful documentation is what establishes you as the frontend owner."},{"point":"By 90 — own the roadmap.","detail":"Now propose the next structural bets — state strategy, charting approach, testing/CI — backed by what you found in the first two months. You''re setting direction, not just taking tickets, which is what ''own the frontend'' actually means."},{"point":"Tone: high ownership, low ego.","detail":"Delivering early is how you earn the mandate to make bigger calls — you''re not assuming authority on day one, you''re earning it fast. That framing reassures a founder who''s kept the codebase tidy himself and is now handing it over."}]'::jsonb, 'medium'::interview_difficulty, '{}', false, NULL);
INSERT INTO interview_questions (category_id, story_id, question, model_answer, tips, difficulty, tags, is_custom, source) VALUES ((SELECT id FROM interview_categories WHERE slug = 'houston-day-to-day'), NULL, 'You''d work closely with Harry, a hands-on technical founder. How do you collaborate with — and sometimes disagree with — a founder?', NULL, '[{"point":"Default to his context.","detail":"Harry knows the customers and the maths better than you will for a while, so start from curiosity about why things are the way they are. Bringing engineering judgement without ego — not ''this is wrong'' but ''here''s a trade-off I''m seeing'' — keeps you a trusted partner rather than a critic."},{"point":"Disagree with evidence, not opinion.","detail":"When you do push back, make it concrete: prototype the alternative, show the numbers, let the data decide. It depersonalizes the disagreement and plays straight to a technical founder''s instincts."},{"point":"Anchor: the Safebooks lazy-load story.","detail":"Use it — a PM wanted all 15+ integrations on first paint; instead of arguing, you built a prototype showing the LCP cost plus usage data proving people touched only a few, proposed lazy-loading, and he agreed. The same playbook works with a founder."},{"point":"Over-communicate in writing.","detail":"He''s technical and busy, so make decisions easy to review async — short written rationales, clear PR descriptions, options with a recommendation. Strong written communication is what makes remote ownership actually function."}]'::jsonb, 'medium'::interview_difficulty, '{}', false, NULL);
INSERT INTO interview_questions (category_id, story_id, question, model_answer, tips, difficulty, tags, is_custom, source) VALUES ((SELECT id FROM interview_categories WHERE slug = 'houston-day-to-day'), NULL, 'This is an early-stage startup, not an enterprise. How does your way of working change?', NULL, '[{"point":"Bias to ship; smaller slices.","detail":"Enterprise rewards thoroughness; an early startup rewards learning fast, so you cut work into smaller pieces that get in front of users sooner. You optimise for feedback, not for covering every edge case up front."},{"point":"Quality that protects velocity, not gold-plating.","detail":"Keep the cheap, high-leverage guardrails — types, a few tests on the critical paths, CI — and consciously skip the heavyweight process that only pays off at scale. The skill is knowing which corner is safe to cut and which isn''t."},{"point":"Comfortable with many hats and ambiguity.","detail":"You''ll define the missing process rather than wait for someone to hand it to you, and you''re fine owning things outside a narrow lane. That self-direction is exactly what a tiny team needs from a senior hire."},{"point":"Be honest about the transition.","detail":"Acknowledge you''re coming from structured Safebooks/Emerline setups, and frame the move as energising — you want more ownership and less process — rather than pretending you''ve always worked startup-style. They know your background, so self-aware honesty lands better than a stretch."}]'::jsonb, 'medium'::interview_difficulty, '{}', false, NULL);
INSERT INTO interview_questions (category_id, story_id, question, model_answer, tips, difficulty, tags, is_custom, source) VALUES ((SELECT id FROM interview_categories WHERE slug = 'houston-day-to-day'), NULL, 'How do you keep quality high at startup speed without over-engineering?', NULL, '[{"point":"Negotiate scope, not standards.","detail":"When time is tight you trim what you build, not the quality of what you ship — drop a feature, not the tests on the money path. Holding that line is what stops a fast startup from drowning in bugs by month six."},{"point":"Cheap guardrails first.","detail":"Strict TypeScript, ESLint/Prettier/Husky, a thin layer of integration tests on critical flows, and visual-regression on charts catch most regressions for very little ongoing cost. They''re the 20% of testing effort that prevents 80% of incidents."},{"point":"Add complexity only when data justifies it.","detail":"Your own lesson: early-career you over-engineered, so now you ship the simplest correct version and let evidence pull you toward more abstraction. That restraint is especially valuable in a small codebase that one person owns."}]'::jsonb, 'medium'::interview_difficulty, '{}', false, NULL);
INSERT INTO interview_questions (category_id, story_id, question, model_answer, tips, difficulty, tags, is_custom, source) VALUES ((SELECT id FROM interview_categories WHERE slug = 'houston-day-to-day'), NULL, 'How do you decide what to build when the roadmap or requirements are vague?', NULL, '[{"point":"Start from the user''s decision.","detail":"Before building, ask what the analyst is actually trying to conclude and what''s slowing them down — the requirement becomes obvious once the underlying decision is clear. It also stops you from building the wrong thing very efficiently."},{"point":"Smallest slice that tests the hypothesis.","detail":"Ship the thinnest version that tells you whether the idea works, then iterate on real feedback instead of speculating. In an early startup, learning fast beats a polished guess."},{"point":"Prototype to surface unknowns.","detail":"A quick prototype turns vague debate into something concrete to react to — the same move as the lazy-load story, using a build to resolve ambiguity. Product instinct is knowing which details users feel and which don''t matter, and protecting the first while cutting the second."}]'::jsonb, 'medium'::interview_difficulty, '{}', false, NULL);
INSERT INTO interview_questions (category_id, story_id, question, model_answer, tips, difficulty, tags, is_custom, source) VALUES ((SELECT id FROM interview_categories WHERE slug = 'houston-day-to-day'), NULL, 'You''d be an early / near-solo frontend hire. How do you handle the breadth and the isolation?', NULL, '[{"point":"You''re comfortable as the FE owner.","detail":"You''ve carried end-to-end ownership before — the Safebooks rendering layer, and driving the Emerline component library across five teams — so being the frontend point person isn''t daunting. Lead with that track record rather than treating solo ownership as a risk."},{"point":"Stay connected deliberately.","detail":"Owning the frontend doesn''t mean working alone in a hole: keep a tight loop with Harry and Bohdan, ask for review even when it''s lightweight, and stay close to users. Isolation is a risk you actively manage, not an inevitability."},{"point":"Document so the team scales after you.","detail":"Write short architecture decision records so the next hires inherit context instead of tribal knowledge. Owning the frontend well means making it legible to others, not building a silo only you understand."}]'::jsonb, 'medium'::interview_difficulty, '{}', false, NULL);
INSERT INTO interview_questions (category_id, story_id, question, model_answer, tips, difficulty, tags, is_custom, source) VALUES ((SELECT id FROM interview_categories WHERE slug = 'houston-day-to-day'), NULL, 'What does a ''good'' frontend codebase look like to you? (They want someone who ''can''t leave a messy module alone''.)', NULL, '[{"point":"Clear boundaries and predictable data flow.","detail":"A good frontend has obvious module seams, state co-located near where it''s used, typed edges, and data that flows one way so you can reason about it. You can open a file cold and predict where things live."},{"point":"Readable over clever; consistent conventions.","detail":"Code is read far more than it''s written, so boring-and-consistent beats clever-and-surprising, and dead code gets deleted rather than left to rot. Consistency is what lets a small team move fast without stepping on each other."},{"point":"Yes, I refactor — but disciplined.","detail":"You genuinely can''t leave a messy module alone, which is what they want, but you do it behind tests and in small reviewable steps, never a risky big-bang rewrite. That''s the mature version of the instinct they''re hiring for."}]'::jsonb, 'medium'::interview_difficulty, '{}', false, NULL);
INSERT INTO interview_questions (category_id, story_id, question, model_answer, tips, difficulty, tags, is_custom, source) VALUES ((SELECT id FROM interview_categories WHERE slug = 'houston-day-to-day'), NULL, 'How will remote work across Ukraine ↔ UK actually work day-to-day?', NULL, '[{"point":"Timezone is the easy part.","detail":"EET is just UK+2, so your working day overlaps theirs almost entirely — far simpler than the US-EU splits you''ve handled for years. Sync meetings and pairing are never a scheduling problem."},{"point":"Async-first habits.","detail":"Four-plus years of remote work with international teams means you default to clear PRs, written decisions and visible progress — the practices that make distributed work actually function. You won''t need hand-holding to be effective remotely."},{"point":"Logistics are clean.","detail":"FOP contractor model at ~5% tax, no visa or sponsorship needed, and immediate availability — there''s no friction for them to hire you. State it plainly so it never becomes an unknown they worry about."}]'::jsonb, 'easy'::interview_difficulty, '{}', false, NULL);
INSERT INTO interview_questions (category_id, story_id, question, model_answer, tips, difficulty, tags, is_custom, source) VALUES ((SELECT id FROM interview_categories WHERE slug = 'houston-day-to-day'), NULL, 'Why Houston Systems, and why this role?', NULL, '[{"point":"The product is squarely your lane.","detail":"A data-dense financial analytics dashboard is exactly what you built at Safebooks — 1M+ transactions, 50k-point real-time views — so this isn''t a stretch, it''s a continuation with more ownership. Name the specifics so it''s clearly not a generic pitch."},{"point":"You want exactly this ownership.","detail":"The role explicitly offers architecture, quality and roadmap ownership of the frontend, which is the level you''re aiming for. Match your wanting to their offering directly — that alignment is itself a strong reason to hire you."},{"point":"Founder and stage fit you.","detail":"Early-stage plus a technical, mathematical founder means real impact and colleagues who care about craft, and your Physics background means you genuinely enjoy the statistical domain rather than tolerating it. That''s a specific, credible reason — not ''I love startups.''"}]'::jsonb, 'easy'::interview_difficulty, '{}', false, NULL);
INSERT INTO interview_questions (category_id, story_id, question, model_answer, tips, difficulty, tags, is_custom, source) VALUES ((SELECT id FROM interview_categories WHERE slug = 'houston-ask-them'), NULL, 'Sharp questions to ask the team (pick 4–5).', NULL, '[{"point":"What does the frontend architecture look like today, and the biggest pain point you''d want fixed first?","detail":"Asking this shows you''re already thinking like the owner, and the answer tells you exactly where you''d make early impact. It also quietly tests whether the ''clean codebase'' claim matches reality."},{"point":"Was ''Context, no Redux'' a deliberate philosophy or a stage choice — and how open are you to evolving it?","detail":"This probes whether the decision is considered or a default, and signals you understand the trade-offs without being preachy about them. How they answer reveals a lot about how they make technical decisions."},{"point":"How do you split work between Chart.js and Recharts today, and have you hit performance ceilings?","detail":"It''s a domain-specific question only a serious frontend person would ask, and it opens a real technical conversation in your strongest area. You may also learn where the product is already straining."},{"point":"How close can I get to the analysts who use this — can I watch them work?","detail":"Signals product instinct — you want to build for real users, not tickets — and access to users is a genuine green flag about how they operate. It also hints at how user-centred the culture really is."},{"point":"With Harry hands-on, what does ''owning the frontend'' mean in practice — where''s my call vs a shared one?","detail":"A respectful way to clarify decision rights before you join, so you understand where your authority ends and a shared call begins. Far better to surface this now than discover a mismatch three months in."},{"point":"What''s the state of testing / CI, and what would ''great'' look like to you?","detail":"Tells you how much foundation already exists versus how much you''d be building, and shows you value sustainable quality. Their bar for ''great'' reveals their engineering standards."},{"point":"What does success for this hire look like at 6 months — and team size / funding / runway?","detail":"A clear success definition tells you what they actually need from you, and stage/runway questions are fair and expected from a senior weighing an early-stage role. Asking shows you''re evaluating them too, which reads as confidence."}]'::jsonb, 'easy'::interview_difficulty, '{}', false, NULL);
INSERT INTO interview_questions (category_id, story_id, question, model_answer, tips, difficulty, tags, is_custom, source) VALUES ((SELECT id FROM interview_categories WHERE slug = 'houston-ask-them'), NULL, 'Company snapshot — what to know walking in.', NULL, '[{"point":"Who they are.","detail":"Houston Systems Ltd is an early-stage UK startup, London-registered and incorporated in 2024 — so expect small-team, founder-led, building-it-now energy rather than established process. Knowing the stage sets your expectations for the whole conversation."},{"point":"What the product does.","detail":"A financial analytics platform for blue-chip clients doing regression analysis, peer comparison and rule-based evaluation, delivered as a fast, data-dense React app on a Python/FastAPI backend — and analysts use it to make real decisions, so trust and correctness matter as much as speed. This is the context every answer should tie back to."},{"point":"Who Harry is.","detail":"Your interviewer and founder is a Cambridge engineering-mathematician with an ML and scientific-computing background who previously founded Phonebox App — so expect technical depth and math literacy, and lean into your Physics background. He''ll value precision and evidence over buzzwords."},{"point":"Who else, and the format.","detail":"Bohdan Lysianskyi is on the thread and likely engineering, so treat part of this as a peer technical chat; the round runs about an hour, meeting more of the team, going deeper technically and on how you''d work day-to-day. Walk in expecting both depth and working-style questions."}]'::jsonb, 'easy'::interview_difficulty, '{}', false, NULL);
INSERT INTO interview_questions (category_id, story_id, question, model_answer, tips, difficulty, tags, is_custom, source) VALUES ((SELECT id FROM interview_categories WHERE slug = 'houston-technical'), NULL, 'How do you keep the UI responsive while filtering or recomputing a large dataset?', NULL, '[{"point":"Mark the expensive update as non-urgent with useTransition.","detail":"When a filter change triggers a heavy re-render — re-slicing 50k rows, redrawing charts — wrapping that state update in startTransition tells React 18 to keep the input responsive and render the heavy result in the background with a pending state. The typed value updates instantly; the chart catches up without freezing the field. It''s React''s built-in answer to exactly their density problem."},{"point":"Or useDeferredValue to lag the expensive consumer.","detail":"If you don''t own the setter (a controlled search box), useDeferredValue hands you a slightly-stale copy to pass to the heavy chart/table, so typing stays smooth while the heavy view trails a frame or two. Same idea, from the consumer side."},{"point":"It only helps if the heavy child is memoized.","detail":"Concurrent features do nothing unless the expensive child is wrapped in React.memo with stable props, so it re-renders only when the deferred value changes — otherwise you''ve just moved the same cost around. Confirm with the Profiler that the transition is actually paying off."},{"point":"Anchor.","detail":"Frame it as the modern version of my Safebooks work: there I hit sub-200ms with virtualization and web workers; on React 18 I''d reach for concurrent features first for filter and interaction responsiveness, then heavier machinery only if profiling demands it."}]'::jsonb, 'hard'::interview_difficulty, '{}', false, NULL);
INSERT INTO interview_questions (category_id, story_id, question, model_answer, tips, difficulty, tags, is_custom, source) VALUES ((SELECT id FROM interview_categories WHERE slug = 'houston-technical'), NULL, 'When is useEffect the wrong tool, and how do you avoid data-fetching race conditions?', NULL, '[{"point":"Most ''derived state'' needs no effect.","detail":"A common smell is using useEffect to compute state from props or other state — that should just be computed during render, or useMemo if genuinely expensive. Effects are for synchronizing with things outside React: the network, the DOM, subscriptions, timers. Knowing that boundary is a strong senior signal."},{"point":"Fetching in effects has a built-in race.","detail":"If filters change quickly, request A can resolve after request B and overwrite newer data with stale results. You fix it with a cleanup flag or an AbortController that cancels or ignores the in-flight request when the effect re-runs. Naming this shows you''ve been bitten by it in real dashboards."},{"point":"Prefer a query library for server state.","detail":"TanStack Query handles cancellation, dedup, caching and stale-while-revalidate for you, so I''d lean on it over hand-rolled effects for the FastAPI calls — less bug surface, better UX. Effects stay for genuine side-effects."},{"point":"Clean up everything.","detail":"Subscriptions, intervals, event and resize listeners all need teardown in the effect''s cleanup, or you leak memory and get zombie updates — especially on a dashboard people leave open all day."}]'::jsonb, 'medium'::interview_difficulty, '{}', false, NULL);
INSERT INTO interview_questions (category_id, story_id, question, model_answer, tips, difficulty, tags, is_custom, source) VALUES ((SELECT id FROM interview_categories WHERE slug = 'houston-technical'), NULL, 'Why does a live/external store need useSyncExternalStore — what is tearing?', NULL, '[{"point":"Tearing = one paint, two values.","detail":"Under concurrent rendering React can pause mid-render; if an external store updates during that pause, some components in the same paint read the old value and others the new one, so the UI is momentarily inconsistent. It''s the subtle bug that makes rolling your own store risky in React 18."},{"point":"useSyncExternalStore is the safe subscription primitive.","detail":"It lets an external store — or a Zustand/Jotai-style store — subscribe so React always renders a consistent snapshot, and it works with server rendering. Any selector store I''d propose for their live data sits on this hook underneath."},{"point":"It also enables slice subscriptions.","detail":"Unlike Context''s all-or-nothing fan-out, a store on this hook lets each component subscribe to just the field it needs — the re-render win for dense dashboards. It ties the point straight back to the Context-vs-store discussion."}]'::jsonb, 'hard'::interview_difficulty, '{}', false, NULL);
INSERT INTO interview_questions (category_id, story_id, question, model_answer, tips, difficulty, tags, is_custom, source) VALUES ((SELECT id FROM interview_categories WHERE slug = 'houston-technical'), NULL, 'How do you stop one broken widget from taking down the whole dashboard?', NULL, '[{"point":"Wrap widgets in error boundaries.","detail":"An error boundary catches render and lifecycle exceptions in its subtree and shows a fallback instead of unmounting the whole app — essential for a dashboard of independent widgets fed by separate API calls. One failing chart shows an inline error card while the rest keep working."},{"point":"Granularity matters.","detail":"I''d put a boundary around each widget plus a top-level catch-all, so a failure is isolated to the smallest sensible unit, and pair it with a retry action and error logging for observability."},{"point":"They don''t catch async or event errors.","detail":"Boundaries only catch render-phase errors, so promise rejections and event handlers still need try/catch and explicit error state. Knowing that limit is the detail that separates people who''ve actually used them."},{"point":"Anchor.","detail":"Resilience like this is the same instinct as modeling loading/error/empty states explicitly — for analysts making real decisions, a clear ''this failed, retry'' beats a blank pane or a white screen."}]'::jsonb, 'medium'::interview_difficulty, '{}', false, NULL);
INSERT INTO interview_questions (category_id, story_id, question, model_answer, tips, difficulty, tags, is_custom, source) VALUES ((SELECT id FROM interview_categories WHERE slug = 'houston-technical'), NULL, 'How do you wrap Chart.js (imperative, canvas) cleanly in React?', NULL, '[{"point":"Create once, update in place.","detail":"Instantiate the chart in an effect against a ref''d canvas on mount, then on data/option changes mutate chart.data / chart.options and call chart.update() — don''t destroy and recreate on every render, that''s janky and leaks. Recreate only when something structural like the chart type changes."},{"point":"Always destroy on unmount.","detail":"Return chart.destroy() from the effect cleanup or you leak canvases and listeners — brutal on a dashboard where widgets mount and unmount as users navigate. It''s the single most common Chart.js-in-React bug."},{"point":"Keep React out of the canvas.","detail":"React owns the container and props; the chart owns the pixels. Pass data down and let the imperative update() reconcile rather than making React re-render the chart, and keep the ref and callbacks stable."},{"point":"Anchor.","detail":"This imperative-library-in-declarative-React boundary is exactly the kind of thing I like getting right — same discipline as the StateBridge I built for the Inango jQuery→React migration."}]'::jsonb, 'hard'::interview_difficulty, '{}', false, NULL);
INSERT INTO interview_questions (category_id, story_id, question, model_answer, tips, difficulty, tags, is_custom, source) VALUES ((SELECT id FROM interview_categories WHERE slug = 'houston-technical'), NULL, 'How do you make charts responsive and handle resize without thrashing?', NULL, '[{"point":"ResizeObserver over window resize.","detail":"Observe the chart''s container with ResizeObserver so it reacts to layout changes — sidebar toggles, split panes — not just window resizes. It''s more accurate and only fires when that element actually changes size."},{"point":"Coalesce redraws with rAF or a debounce.","detail":"Resize can fire dozens of times a second, so batch to one redraw per frame with requestAnimationFrame or a short debounce; otherwise dragging a panel divider tanks the frame rate."},{"point":"Mind devicePixelRatio.","detail":"On canvas you must scale by devicePixelRatio or charts look blurry on retina and 4K displays — a small detail analysts on nice monitors notice, and it fits the craft bar they screen for."}]'::jsonb, 'medium'::interview_difficulty, '{}', false, NULL);
INSERT INTO interview_questions (category_id, story_id, question, model_answer, tips, difficulty, tags, is_custom, source) VALUES ((SELECT id FROM interview_categories WHERE slug = 'houston-technical'), NULL, 'How would you synchronize multiple charts — shared crosshair, linked zoom/pan?', NULL, '[{"point":"Lift the shared interaction state up.","detail":"Hover position, zoom window and selected range live in a shared parent (Context or a small store); each chart reads from it and reports into it. That''s what makes a crosshair track across a stack of charts or a zoom apply to all of them at once."},{"point":"Broadcast, don''t couple.","detail":"Each chart subscribes to the shared range and renders its own view; they never talk to each other directly. That keeps them composable so you can add or remove charts freely."},{"point":"Throttle the shared updates.","detail":"Hover and zoom fire constantly, so throttle with rAF before writing to shared state or you re-render every linked chart on every mouse move. This is where the selector-store pattern pays off — only subscribed charts update."}]'::jsonb, 'hard'::interview_difficulty, '{}', false, NULL);
INSERT INTO interview_questions (category_id, story_id, question, model_answer, tips, difficulty, tags, is_custom, source) VALUES ((SELECT id FROM interview_categories WHERE slug = 'houston-technical'), NULL, 'Live financial data: WebSocket vs SSE vs polling — how do you choose?', NULL, '[{"point":"Match the transport to the data pattern.","detail":"Polling is simplest and fine for slow or periodic updates; SSE streams one-way server→client over plain HTTP with built-in auto-reconnect; WebSocket is for high-frequency or bidirectional. For a mostly-read analytics dashboard, SSE often hits the sweet spot with less operational weight than WebSockets."},{"point":"Plan for reconnection and gaps.","detail":"Networks drop, so you need reconnect with backoff, a way to resync missed data (last-event-id or a refetch), and clear indication of stale data in the UI. Analysts must never act on silently stale numbers."},{"point":"Handle ordering and backpressure.","detail":"Out-of-order or bursty messages need sequencing and coalescing — batch updates to one render per frame rather than re-rendering per message, or a busy feed melts the main thread."},{"point":"Anchor.","detail":"At Safebooks I surfaced anomalies across 1M+ daily transactions with live updates, so I''ve handled the batching and backpressure side of streaming into a dense UI."}]'::jsonb, 'hard'::interview_difficulty, '{}', false, NULL);
INSERT INTO interview_questions (category_id, story_id, question, model_answer, tips, difficulty, tags, is_custom, source) VALUES ((SELECT id FROM interview_categories WHERE slug = 'houston-technical'), NULL, 'Peer comparison means big tables. How do you handle a large sortable, filterable grid?', NULL, '[{"point":"Virtualize the rows.","detail":"Render only the visible rows plus a small buffer (react-window / TanStack Virtual) so a 50k-row peer table stays smooth — DOM node count, not data size, is what kills table performance."},{"point":"Headless grid for control, AG Grid for batteries-included.","detail":"TanStack Table gives you sorting/filtering/grouping logic while you own the markup for a bespoke design; AG Grid brings pivoting, cell editing and export out of the box if they need enterprise-grid features fast. I''d choose based on how custom the UI must be."},{"point":"Push heavy sort/filter to the server past a threshold.","detail":"Client-side sort and filter is fine for a few thousand rows; beyond that, do it on the FastAPI side and stream pages so the browser isn''t holding and churning the whole dataset. Knowing where that line sits and choosing deliberately is the point."},{"point":"Anchor.","detail":"This is the tabular sibling of my Safebooks dashboard work — same virtualization and measure-the-real-bottleneck mindset."}]'::jsonb, 'hard'::interview_difficulty, '{}', false, NULL);
INSERT INTO interview_questions (category_id, story_id, question, model_answer, tips, difficulty, tags, is_custom, source) VALUES ((SELECT id FROM interview_categories WHERE slug = 'houston-technical'), NULL, 'What do you watch for in financial number formatting and time-series data?', NULL, '[{"point":"Use Intl.NumberFormat, not hand-rolled formatting.","detail":"Locale-aware currency, thousands separators and controlled decimal precision come free and correct with Intl.NumberFormat, whereas rolling your own gets rounding and locale wrong. Cache the formatter instances — creating them per cell in a big grid is a real perf cost."},{"point":"Be deliberate about rounding and precision.","detail":"Financial figures need consistent, documented rounding, and sometimes you display rounded while computing on the raw value; an off-by-a-cent from naive toFixed erodes analyst trust. Never imply more precision than the data has."},{"point":"Time series have traps.","detail":"Timezones (store and compute in UTC, render local), market-hour gaps and holidays (don''t draw misleading straight lines across closed periods), and resampling per zoom level all need handling. These are exactly the details a careful analyst notices."}]'::jsonb, 'medium'::interview_difficulty, '{}', false, NULL);
INSERT INTO interview_questions (category_id, story_id, question, model_answer, tips, difficulty, tags, is_custom, source) VALUES ((SELECT id FROM interview_categories WHERE slug = 'houston-technical'), NULL, 'Design a type-safe, reusable API for a chart or table component.', NULL, '[{"point":"Generics over the row/datum type.","detail":"A table typed as Table<T> with column definitions keyed to keyof T means the compiler catches a mistyped accessor or a formatter applied to the wrong field, so the component is reusable across datasets without losing type safety. This is where advanced generics earn their keep."},{"point":"Discriminated unions for variant config.","detail":"Model chart or widget config as a union tagged by type (line, bar, scatter …) so each variant only allows its valid options and exhaustive switches are checked. It makes illegal configurations unrepresentable."},{"point":"Design the API for the caller.","detail":"Good component APIs are hard to misuse: sensible defaults, required props that must be set, and inference so callers rarely annotate. I''d use the satisfies operator and inference to keep call sites clean."},{"point":"Anchor.","detail":"This is the work behind my Safebooks TS-generics data layer (~95% fewer runtime errors) and the 60+ component Emerline library — reusable, typed component APIs are a core strength."}]'::jsonb, 'hard'::interview_difficulty, '{}', false, NULL);
INSERT INTO interview_questions (category_id, story_id, question, model_answer, tips, difficulty, tags, is_custom, source) VALUES ((SELECT id FROM interview_categories WHERE slug = 'houston-technical'), NULL, 'How would you architect this dashboard''s frontend from scratch?', NULL, '[{"point":"Clarify first: scale, data shape, update frequency.","detail":"I''d start by asking how many widgets and points, how live the data is, how many concurrent clients, and what the analyst''s core workflow is — the architecture follows the answers rather than starting from a stack. Asking those questions is itself the senior signal."},{"point":"Layered structure.","detail":"Feature/widget modules with clear boundaries; a typed API/data layer (OpenAPI→TS plus a query cache); a shared charting and primitives layer; state layered local → URL → server-cache → shared. Conventions enforced by ESLint/Prettier/Husky and captured as ADRs."},{"point":"A composable widget system.","detail":"Dashboards live or die on the widget abstraction — consistent loading/error/empty states, an error boundary per widget, lazy-loading for heavy ones, and a layout system. Get that contract right and adding features stays cheap."},{"point":"Name the cross-cutting concerns.","detail":"A performance budget with Web Vitals monitoring, auth and route protection (Clerk), a testing strategy (integration plus visual regression on charts), and preview-deploy CI on Vercel. Thinking beyond components reads as ownership."}]'::jsonb, 'hard'::interview_difficulty, '{}', false, NULL);
INSERT INTO interview_questions (category_id, story_id, question, model_answer, tips, difficulty, tags, is_custom, source) VALUES ((SELECT id FROM interview_categories WHERE slug = 'houston-technical'), NULL, 'How do you test charts and data-heavy components?', NULL, '[{"point":"Visual regression for the pixels.","detail":"Canvas and SVG output is hard to assert with normal queries, so snapshot the rendered chart with Chromatic or Playwright screenshots and diff on change — that catches visual breakage unit tests miss. I used Chromatic on the Emerline library."},{"point":"Unit-test the pure logic, integration-test the behavior.","detail":"Downsampling, scale/domain calc, formatting and filtering are pure functions that get fast unit tests; the interactive bits (tooltip appears, filter updates the table) get integration tests with React Testing Library. Test what the user experiences, not internals."},{"point":"Mock the API boundary.","detail":"Mock Axios or the query layer with MSW so data components are tested deterministically against fixtures, including loading and error paths, then add a thin layer of Playwright E2E on the critical analyst flow."},{"point":"Anchor.","detail":"At Safebooks 85% coverage was a byproduct of testing the right layers, not a target — same philosophy here."}]'::jsonb, 'medium'::interview_difficulty, '{}', false, NULL);
INSERT INTO interview_questions (category_id, story_id, question, model_answer, tips, difficulty, tags, is_custom, source) VALUES ((SELECT id FROM interview_categories WHERE slug = 'houston-technical'), NULL, 'Clerk auth: how would you handle protected routes, sessions, and multi-tenant access?', NULL, '[{"point":"Gate routes with the session.","detail":"Wrap the app in Clerk''s provider, guard routes so unauthenticated users are redirected, and read the session and user from Clerk''s hooks — conceptually identical to the Firebase Auth flows I''ve shipped (sessions, protected routes, token refresh), so I''d be productive quickly."},{"point":"Attach the token at the API boundary.","detail":"An Axios interceptor injects the Clerk session token on each request and handles 401s by refreshing or bouncing to sign-in — one central place, not per call. Clean and testable."},{"point":"Multi-tenant for blue-chip clients.","detail":"If clients are isolated, Clerk''s organizations and roles map to that — scope data and UI by active org, and never rely on the frontend alone for isolation, the backend must enforce it too. Raising this shows I''m thinking about their actual customer model."}]'::jsonb, 'medium'::interview_difficulty, '{}', false, NULL);
INSERT INTO interview_questions (category_id, story_id, question, model_answer, tips, difficulty, tags, is_custom, source) VALUES ((SELECT id FROM interview_categories WHERE slug = 'houston-technical'), NULL, 'What frontend security concerns matter for a financial analytics app?', NULL, '[{"point":"XSS is the main frontend risk.","detail":"Anywhere you render analyst-supplied content — rule names, notes, imported labels — must be treated as untrusted; React escapes by default, so the danger is dangerouslySetInnerHTML and unsanitized HTML. Avoid it, or sanitize with DOMPurify."},{"point":"Handle tokens carefully.","detail":"Prefer the auth provider''s secure storage over hand-rolling tokens in localStorage where possible, scope what''s exposed to the client, and never put secrets in the bundle or in URLs. Clerk handles most of this if you don''t fight it."},{"point":"Don''t leak data client-side.","detail":"Enforce authorization on the backend rather than by hiding UI, be careful what ends up in logs, error messages and analytics, and set a sensible CSP. For a tool serving blue-chip financial data, data-handling discipline is part of the job."}]'::jsonb, 'medium'::interview_difficulty, '{}', false, NULL);
INSERT INTO interview_questions (category_id, story_id, question, model_answer, tips, difficulty, tags, is_custom, source) VALUES ((SELECT id FROM interview_categories WHERE slug = 'houston-technical'), NULL, 'How would you approach a live coding exercise or code review in this round?', NULL, '[{"point":"Think out loud — they''re buying your reasoning.","detail":"In a live exercise the process matters more than a flawless answer: restate the problem, state assumptions, name the approach and trade-offs before coding, and narrate as you go. Going silent is the thing to avoid."},{"point":"Start simple, then iterate.","detail":"Get the simplest correct version working and then improve — the same anti-over-engineering habit I bring day-to-day — and ask clarifying questions rather than guessing at requirements."},{"point":"For a code review, lead with the why.","detail":"If they hand me code to critique, I separate blocking issues from nits, explain the reasoning, and stay specific and kind — checking correctness, boundaries and readability before style. It''s how I run reviews normally."},{"point":"Treat it as collaboration.","detail":"Ask questions, take hints gracefully, and pull them into the problem — it previews what pairing with me is like, which is half of what they''re assessing."}]'::jsonb, 'medium'::interview_difficulty, '{}', false, NULL);
INSERT INTO interview_sessions (slug, company, role, round, scheduled_at, status, product, interviewers, likely_topics, your_numbers, bottom_line, stack_map, focus_category_ids) VALUES ('houston-systems-round-2', 'Houston Systems', 'Senior Frontend Engineer', 'Round 2 · Technical', '2026-07-03T07:00:00Z', 'upcoming'::interview_session_status, 'A financial analytics platform for blue-chip companies. It does regression analysis, peer comparison, and rule-based evaluation, served through a fast, data-dense React app on a Python/FastAPI backend. Analysts use it to make real decisions — so correctness, legibility and trust matter as much as speed.', '[{"name":"Harry Blakiston Houston","role":"Founder / Director","focus":"Cambridge engineering-mathematician; ML & scientific-computing background; ex-founder of Phonebox App. Hands-on and technical — expect math-literate depth and a focus on how you think."},{"name":"Bohdan Lysianskyi","role":"Team (likely)","focus":"Colleague on the thread, likely engineering. Treat as a peer-level technical conversation; show you''d be easy and rigorous to build alongside."}]'::jsonb, '[{"topic":"Charting library choice & dropping to canvas/D3","whereToDrill":"Houston · Technical"},{"topic":"State architecture with React Context without re-render storms","whereToDrill":"Houston · Technical"},{"topic":"Profiling before optimising","whereToDrill":"Houston · Technical"}]'::jsonb, '[{"label":"Live data points rendered","value":"50,000+ sub-200ms (Safebooks anomaly dashboard)"},{"label":"Lighthouse (Safebooks)","value":"62 → 95+"},{"label":"LCP","value":"4.2s → 1.5s"},{"label":"INP","value":"450ms → 100ms"},{"label":"Fewer runtime errors via TS generics + Zod","value":"~95%"},{"label":"Daily transactions","value":"1M+ (financial governance platform)"},{"label":"Component library adoption","value":"60+ components, 5 teams (−30% UI time)"},{"label":"jQuery→React migration load time","value":"−74% (Inango), zero downtime"}]'::jsonb, 'Round 1 (18 June) went well — Harry was "impressed by what you shared." This round goes deeper on the technical side and how you''d approach the work day-to-day.', '[{"theirTech":"React 18","yourStanding":"Expert · daily driver at Safebooks & Emerline"},{"theirTech":"React Context (no Redux)","yourStanding":"Strong · know the re-render pitfalls cold; ready to discuss split contexts + when a selector store beats Context"},{"theirTech":"Chart.js + Recharts","yourStanding":"Strong · built dense charting; canvas (Chart.js) for density, SVG (Recharts) for interactivity"},{"theirTech":"Axios","yourStanding":"Strong · centralize with typed wrappers + interceptors for auth/errors"},{"theirTech":"Clerk (auth)","yourStanding":"Learn fast · not used Clerk; have shipped hosted auth (Firebase) — same shape. Don''t bluff it"},{"theirTech":"Vercel","yourStanding":"Comfortable · deployed Next.js there — preview deploys, env, edge/serverless"},{"theirTech":"Next.js / React Router (nice-to-have)","yourStanding":"Next.js advanced (Safebooks); React Router solid. Their app is likely a Vite SPA"},{"theirTech":"Python / FastAPI (bonus)","yourStanding":"Boundary-comfortable · haven''t written FastAPI, but worked against Python APIs; would type the edge via OpenAPI → TS"},{"theirTech":"Financial / statistical knowledge (bonus)","yourStanding":"Genuine edge · Physics Master''s + Safebooks fintech domain. Speak Harry''s language"}]'::jsonb, ARRAY(SELECT id FROM interview_categories WHERE slug IN ('houston-technical', 'houston-day-to-day', 'houston-ask-them'))) ON CONFLICT (slug) DO NOTHING;
